    if _vazio(v):
        return None
    if isinstance(v, float) and v.is_integer():
        v = int(v)
    return str(v).strip()


def _cnpj(v) -> str:
    c = cnpj14(v)
    if c is None:
        raise ValueError(f"CNPJ inválido: {v!r}")
    return c


