    """Linha do cabeçalho (a que tem a célula "Lojista") e coluna de cada campo."""
    for row in ws.iter_rows():
        if any(sem_acento(c.value) == "LOJISTA" for c in row if isinstance(c.value, str)):
            colunas = {}
            for c in row:
